WITH session_stats AS (SELECT session_id, COUNT(*) AS total_count, ROUND(STDDEV(duration_sec), 2) AS stddev_duration_sec FROM web_events GROUP BY session_id) SELECT sessions.id, sessions.customer_id, session_stats.total_count, session_stats.stddev_duration_sec FROM sessions LEFT OUTER JOIN session_stats ON sessions.id = session_stats.session_id WHERE session_stats.total_count > 6 ORDER BY customer_id DESC
